'use client';

import React from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import {
  LayoutDashboard,
  ShoppingCart,
  Package,
  FileSpreadsheet,
  FileText,
  Settings,
  Shield,
  FilePlus2,
  LogOut,
} from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { useAuth } from '../contexts/AuthContext';
import { useRouter } from 'next/navigation';

export function Sidebar() {
  const pathname = usePathname();
  const { t } = useLanguage();
  const { logout } = useAuth();
  const router = useRouter();

  const items = [
    { href: '/dashboard', label: t('nav.dashboard'), icon: LayoutDashboard },
    { href: '/pos', label: t('nav.pos'), icon: ShoppingCart },
    { href: '/inventory', label: t('nav.inventory'), icon: Package },
    { href: '/manual-entry', label: t('nav.manualEntry'), icon: FilePlus2 },
    { href: '/excel-import', label: t('nav.excelImport'), icon: FileSpreadsheet },
    { href: '/invoices', label: t('nav.invoices'), icon: FileText },
    { href: '/settings', label: t('nav.settings'), icon: Settings },
    { href: '/admin', label: t('nav.admin'), icon: Shield },
  ];

  return (
    <aside className="w-64 bg-[#0a0f18] border-l border-cyan-500/40 flex flex-col justify-between">
      <div>
        <div className="px-6 py-6 border-b border-cyan-500/20 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="text-cyan-400 font-extrabold text-xl">Crown</span>
            <span className="text-xs text-cyan-500/70">SERVICES</span>
          </div>
          <div className="w-9 h-9 rounded-full border border-cyan-500/40 flex items-center justify-center text-cyan-400">
            👑
          </div>
        </div>

        <nav className="px-4 py-4 space-y-2">
          {items.map(({ href, label, icon: Icon }) => {
            const active = pathname === href;
            return (
              <Link
                key={href}
                href={href}
                className={`flex items-center gap-3 px-4 py-3 rounded-xl transition ${
                  active
                    ? 'bg-cyan-500/10 border border-cyan-500/40 text-cyan-300 shadow-[0_0_14px_rgba(0,243,255,0.35)]'
                    : 'text-slate-300 hover:text-cyan-300 hover:bg-cyan-500/10'
                }`}
              >
                <Icon className="h-5 w-5 text-cyan-300" />
                <span className="text-sm font-semibold">{label}</span>
              </Link>
            );
          })}
        </nav>
      </div>

      <div className="px-4 pb-6 space-y-3">
        <button
          onClick={() => {
            logout();
            router.replace('/login');
          }}
          className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-slate-300 hover:text-cyan-300 hover:bg-cyan-500/10 transition border border-cyan-500/20"
        >
          <LogOut className="h-5 w-5 text-cyan-300" />
          <span className="text-sm font-semibold">{t('nav.logout')}</span>
        </button>
        <div className="text-xs text-slate-500 text-center">
          Crown Services — By Ahmed 2025
        </div>
      </div>
    </aside>
  );
}

