'use client';

import React, { useEffect, useState } from 'react';
import { Printer, ShoppingCart, Trash2, X, Image as ImageIcon } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { apiRequest, useAuth } from '../contexts/AuthContext';
import { useCurrency } from '../contexts/CurrencyContext';
import { Sidebar } from '../components/Sidebar';

interface Category {
  id: number;
  name_en: string;
  name_ar: string;
}

interface Product {
  id: number;
  name_en: string;
  name_ar: string;
  brand: string;
  sell_price: number;
  stock_quantity: number;
  category_id: number;
  image_url?: string;
}

interface CartItem {
  productId: number;
  name: string;
  price: number;
  quantity: number;
  total: number;
}

export default function PosPage() {
  const { t, language, direction } = useLanguage();
  const { user } = useAuth();
  const { symbol } = useCurrency();
  const [categories, setCategories] = useState<Category[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<number | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isPrinting, setIsPrinting] = useState(false);

  useEffect(() => {
    loadCategories();
    loadProducts();
  }, []);

  const loadCategories = async () => {
    try {
      const data = await apiRequest('/categories');
      setCategories(data);
      if (data.length > 0) {
        setSelectedCategory(data[0].id);
      }
    } catch (error) {
      console.error('Failed to load categories:', error);
    }
  };

  const loadProducts = async () => {
    try {
      const data = await apiRequest('/products');
      setProducts(data);
    } catch (error) {
      console.error('Failed to load products:', error);
    }
  };

  const filteredProducts = selectedCategory
    ? products.filter((p) => p.category_id === selectedCategory && p.stock_quantity > 0)
    : products.filter((p) => p.stock_quantity > 0);

  const addToCart = (product: Product) => {
    if (product.stock_quantity === 0) return;

    setCart((prev) => {
      const existing = prev.find((item) => item.productId === product.id);
      if (existing) {
        if (existing.quantity >= product.stock_quantity) return prev;
        return prev.map((item) =>
          item.productId === product.id
            ? { ...item, quantity: item.quantity + 1, total: (item.quantity + 1) * item.price }
            : item
        );
      }
      return [
        ...prev,
        {
          productId: product.id,
          name: language === 'ar' ? product.name_ar : product.name_en,
          price: product.sell_price,
          quantity: 1,
          total: product.sell_price,
        },
      ];
    });
  };

  const updateQuantity = (productId: number, delta: number) => {
    setCart((prev) => {
      const item = prev.find((i) => i.productId === productId);
      if (!item) return prev;

      const product = products.find((p) => p.id === productId);
      if (!product) return prev;

      const newQuantity = item.quantity + delta;
      if (newQuantity <= 0) {
        return prev.filter((i) => i.productId !== productId);
      }
      if (newQuantity > product.stock_quantity) return prev;

      return prev.map((i) =>
        i.productId === productId ? { ...i, quantity: newQuantity, total: newQuantity * i.price } : i
      );
    });
  };

  const removeFromCart = (productId: number) => {
    setCart((prev) => prev.filter((item) => item.productId !== productId));
  };

  const clearCart = () => {
    setCart([]);
  };

  const total = cart.reduce((sum, item) => sum + item.total, 0);

  const handleInvoicePayment = async () => {
    if (cart.length === 0) return;
    try {
      const items = cart.map((item) => ({
        productId: item.productId,
        quantity: item.quantity,
        unitPrice: item.price,
      }));

      const sale = await apiRequest('/sales', {
        method: 'POST',
        body: JSON.stringify({ items, paymentMethod: 'invoice' }),
      });

      printReceipt(sale);
      clearCart();
      loadProducts();
    } catch (error) {
      console.error('Invoice print failed:', error);
      alert(language === 'ar' ? 'فشلت العملية' : 'Payment failed');
    }
  };

  const handleCashPayment = async () => {
    if (cart.length === 0) return;

    try {
      const items = cart.map((item) => ({
        productId: item.productId,
        quantity: item.quantity,
        unitPrice: item.price,
      }));

      const sale = await apiRequest('/sales', {
        method: 'POST',
        body: JSON.stringify({ items, paymentMethod: 'cash' }),
      });

      // Print receipt
      printReceipt(sale);

      // Clear cart
      clearCart();

      // Reload products to update stock
      loadProducts();
    } catch (error) {
      console.error('Payment failed:', error);
      alert(language === 'ar' ? 'فشلت العملية' : 'Payment failed');
    }
  };

  const printReceipt = (sale: any) => {
    setIsPrinting(true);

    const receiptWindow = window.open('', '_blank');
    if (!receiptWindow) {
      setIsPrinting(false);
      return;
    }

    const receiptHTML = `
      <!DOCTYPE html>
      <html dir="${language === 'ar' ? 'rtl' : 'ltr'}" lang="${language}">
        <head>
          <meta charset="UTF-8">
          <title>Receipt - ${sale.invoiceNumber || sale.saleId}</title>
          <style>
            @import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@400;700;900&display=swap');
            * { margin: 0; padding: 0; box-sizing: border-box; }
            body {
              font-family: 'Orbitron', monospace;
              background: #0a0a0c;
              color: #00f3ff;
              padding: 40px;
              line-height: 1.6;
            }
            .receipt {
              max-width: 400px;
              margin: 0 auto;
              background: linear-gradient(135deg, #0a0a0c 0%, #1a1a2e 100%);
              border: 2px solid #00f3ff;
              border-radius: 20px;
              padding: 30px;
              box-shadow: 
                0 0 40px rgba(0, 243, 255, 0.5),
                inset 0 0 20px rgba(0, 243, 255, 0.1);
            }
            .header {
              text-align: center;
              margin-bottom: 30px;
              border-bottom: 2px solid #00f3ff;
              padding-bottom: 20px;
            }
            .header h1 {
              font-size: 32px;
              font-weight: 900;
              text-transform: uppercase;
              letter-spacing: 3px;
              text-shadow: 
                0 0 10px #00f3ff,
                0 0 20px #00f3ff,
                0 0 30px #00f3ff;
              margin-bottom: 10px;
            }
            .header p {
              font-size: 12px;
              color: #bc13fe;
              text-transform: uppercase;
              letter-spacing: 2px;
            }
            .info {
              margin-bottom: 25px;
              font-size: 11px;
              color: #888;
            }
            .items {
              margin-bottom: 25px;
            }
            .item {
              display: flex;
              justify-content: space-between;
              padding: 12px 0;
              border-bottom: 1px solid rgba(0, 243, 255, 0.2);
              font-size: 13px;
            }
            .item-name {
              flex: 1;
              color: #fff;
            }
            .item-qty {
              margin: 0 15px;
              color: #bc13fe;
            }
            .item-price {
              color: #00f3ff;
              font-weight: 700;
            }
            .total {
              margin-top: 20px;
              padding-top: 20px;
              border-top: 2px solid #00f3ff;
              display: flex;
              justify-content: space-between;
              font-size: 20px;
              font-weight: 700;
              text-transform: uppercase;
              text-shadow: 0 0 10px #00f3ff;
            }
            .footer {
              margin-top: 30px;
              text-align: center;
              font-size: 10px;
              color: #555;
              text-transform: uppercase;
              letter-spacing: 1px;
            }
            @media print {
              body { padding: 20px; }
              .receipt { box-shadow: none; }
            }
          </style>
        </head>
        <body>
          <div class="receipt">
            <div class="header">
              <h1>CROWN</h1>
              <p>${language === 'ar' ? 'تاج الخدمات' : 'SERVICES SYSTEM'}</p>
            </div>
            <div class="info">
              <p>${language === 'ar' ? 'رقم الفاتورة' : 'Receipt #'}: ${sale.invoiceNumber || sale.saleId}</p>
              <p>${language === 'ar' ? 'التاريخ' : 'Date'}: ${new Date().toLocaleString(language === 'ar' ? 'ar-SA' : 'en-US')}</p>
              <p>${language === 'ar' ? 'الموظف' : 'Cashier'}: ${user?.username || 'N/A'}</p>
            </div>
            <div class="items">
              ${cart.map((item) => `
                <div class="item">
                  <span class="item-name">${item.name}</span>
                  <span class="item-qty">${item.quantity}x</span>
                  <span class="item-price">${item.total.toFixed(2)} ${symbol}</span>
                </div>
              `).join('')}
            </div>
            <div class="total">
              <span>${language === 'ar' ? 'الإجمالي' : 'TOTAL'}</span>
              <span>${total.toFixed(2)} ${symbol}</span>
            </div>
            <div class="footer">
              <p>${language === 'ar' ? 'شكراً لزيارتك!' : 'THANK YOU!'}</p>
            </div>
          </div>
        </body>
      </html>
    `;

    receiptWindow.document.write(receiptHTML);
    receiptWindow.document.close();

    setTimeout(() => {
      receiptWindow.print();
      setIsPrinting(false);
    }, 500);
  };

  return (
    <div className="min-h-screen bg-black text-white flex" dir={direction}>
      <Sidebar />
      <div className="flex-1 p-8 overflow-y-auto">
        <div className="flex items-center justify-between mb-6">
          <h1 className="text-2xl font-bold text-cyan-200">{t('pos.title')}</h1>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Categories & Products */}
          <div className="lg:col-span-2 space-y-6">
            {/* Categories */}
            <div className="neon-box rounded-xl p-4">
              <h2 className="text-xl font-bold mb-4 text-cyan-400">{t('pos.categories')}</h2>
              <div className="flex flex-wrap gap-2">
                {categories.map((cat) => (
                  <button
                    key={cat.id}
                    onClick={() => setSelectedCategory(cat.id)}
                    className={`px-4 py-2 rounded-lg transition ${
                      selectedCategory === cat.id
                        ? 'bg-cyan-600 text-white'
                        : 'bg-gray-800 text-gray-300 hover:bg-gray-700'
                    }`}
                  >
                    {language === 'ar' ? cat.name_ar : cat.name_en}
                  </button>
                ))}
              </div>
            </div>

            {/* Products Grid */}
            <div className="neon-box rounded-xl p-4">
              <h2 className="text-xl font-bold mb-4 text-cyan-400">{t('pos.products')}</h2>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-4 max-h-[600px] overflow-y-auto">
                {filteredProducts.map((product) => (
                  <button
                    key={product.id}
                    onClick={() => addToCart(product)}
                    disabled={product.stock_quantity === 0}
                    className="p-4 bg-[#0d1422] rounded-xl hover:bg-[#111a2b] transition text-right disabled:opacity-50 disabled:cursor-not-allowed border border-cyan-500/20 hover:border-cyan-400/50"
                  >
                    <div className="h-20 w-full rounded-lg border border-cyan-500/30 bg-black/60 flex items-center justify-center mb-3">
                      {product.image_url ? (
                        // eslint-disable-next-line @next/next/no-img-element
                        <img src={product.image_url} alt={product.name_ar} className="h-16 object-contain" />
                      ) : (
                        <ImageIcon className="h-6 w-6 text-cyan-400/60" />
                      )}
                    </div>
                    <h3 className="font-bold text-white mb-1">
                      {language === 'ar' ? product.name_ar : product.name_en}
                    </h3>
                    <p className="text-sm text-gray-400 mb-2">{product.brand}</p>
                    <div className="flex justify-between items-center">
                      <span className="text-cyan-400 font-bold">
                        {product.sell_price.toFixed(2)} {symbol}
                      </span>
                      <span className={`text-xs ${product.stock_quantity > 0 ? 'text-green-400' : 'text-red-400'}`}>
                        {product.stock_quantity} {t('pos.inStock')}
                      </span>
                    </div>
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* Cart */}
          <div className="lg:col-span-1">
            <div className="neon-card rounded-xl p-6 sticky top-6">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-xl font-bold text-cyan-400 flex items-center gap-2">
                  <ShoppingCart className="w-5 h-5" />
                  {t('pos.cart')}
                </h2>
                {cart.length > 0 && (
                  <button onClick={clearCart} className="text-red-400 hover:text-red-300">
                    <Trash2 className="w-5 h-5" />
                  </button>
                )}
              </div>

              <div className="space-y-3 mb-6 max-h-[400px] overflow-y-auto">
                {cart.length === 0 ? (
                  <p className="text-gray-500 text-center py-8">
                    {t('pos.cartEmpty')}
                  </p>
                ) : (
                  cart.map((item) => (
                    <div key={item.productId} className="bg-gray-800 p-3 rounded-lg">
                      <div className="flex justify-between items-start mb-2">
                        <h4 className="font-medium text-white flex-1">{item.name}</h4>
                        <button onClick={() => removeFromCart(item.productId)} className="text-red-400 hover:text-red-300 ml-2">
                          <X className="w-4 h-4" />
                        </button>
                      </div>
                      <div className="flex justify-between items-center">
                        <div className="flex items-center gap-2">
                          <button
                            onClick={() => updateQuantity(item.productId, -1)}
                            className="w-6 h-6 rounded bg-gray-700 hover:bg-gray-600 flex items-center justify-center"
                          >
                            -
                          </button>
                          <span className="text-white font-medium">{item.quantity}</span>
                          <button
                            onClick={() => updateQuantity(item.productId, 1)}
                            className="w-6 h-6 rounded bg-gray-700 hover:bg-gray-600 flex items-center justify-center"
                          >
                            +
                          </button>
                        </div>
                        <span className="text-cyan-400 font-bold">
                          {item.total.toFixed(2)} {symbol}
                        </span>
                      </div>
                    </div>
                  ))
                )}
              </div>

              <div className="border-t border-gray-700 pt-4 mb-4">
                <div className="flex justify-between items-center mb-4">
                  <span className="text-lg font-bold">{t('pos.total')}:</span>
                  <span className="text-2xl font-bold text-cyan-400">
                    {total.toFixed(2)} {symbol}
                  </span>
                </div>
              </div>

              <button
                onClick={handleInvoicePayment}
                disabled={cart.length === 0 || isPrinting}
                className="w-full mb-3 bg-gradient-to-r from-fuchsia-600 to-cyan-600 hover:from-fuchsia-500 hover:to-cyan-500 text-white font-bold py-3 px-6 rounded-lg transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 text-base"
                style={{ boxShadow: '0 0 18px rgba(236,72,153,0.35)' }}
              >
                🧾 {t('pos.printInvoice')}
              </button>

              <button
                onClick={handleCashPayment}
                disabled={cart.length === 0 || isPrinting}
                className="w-full bg-gradient-to-r from-cyan-600 to-purple-600 hover:from-cyan-500 hover:to-purple-500 text-white font-bold py-4 px-6 rounded-lg transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 text-lg"
                style={{ boxShadow: '0 0 20px rgba(0, 243, 255, 0.5)' }}
              >
                {isPrinting ? (
                  <>
                    <Printer className="w-5 h-5 animate-pulse" />
                    {t('pos.printing')}
                  </>
                ) : (
                  <>💵 {t('pos.cash')}</>
                )}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

